export declare const modernEditorialFoundationTheme = "/* \u7F16\u8F91\u90E8\u624B\u8BB0\uFF1A\u9AD8\u4FE1\u606F\u5BC6\u5EA6\u7684\u4E2D\u6587\u5185\u520A\u98CE\u683C */\n#wemd {\n  max-width: 677px;\n  margin: 0 auto;\n  padding: 16px 24px;\n  color: #34362f;\n  background-color: transparent;\n  font-family: -apple-system, BlinkMacSystemFont, \"PingFang SC\", \"Microsoft YaHei\", \"Noto Sans CJK SC\", sans-serif;\n  font-size: 16px;\n  line-height: 1.86;\n  letter-spacing: 0.018em;\n  word-break: break-word;\n  counter-reset: editorial-section;\n}\n\n/* \u6B63\u6587 */\n#wemd p {\n  margin: 0 0 23px;\n  color: #34362f;\n  font-size: 16px;\n  line-height: 1.86;\n  letter-spacing: 0.018em;\n  text-align: justify;\n}\n\n/* \u520A\u5934\u548C\u7AE0\u8282 */\n#wemd h1,\n#wemd h2,\n#wemd h3,\n#wemd h4,\n#wemd h5,\n#wemd h6 {\n  padding: 0;\n  text-align: left;\n}\n\n#wemd h1 {\n  margin: 26px 0 50px;\n  padding: 24px 0 20px;\n  border-top: 5px solid #20221e;\n  border-bottom: 3px solid #c76237;\n  background: transparent;\n}\n\n#wemd h1 .content {\n  color: #20221e;\n  font-family: \"Songti SC\", \"STSong\", \"Noto Serif CJK SC\", SimSun, serif;\n  font-size: 32px;\n  font-weight: 700;\n  line-height: 1.4;\n  letter-spacing: 0.04em;\n}\n\n#wemd h2 {\n  display: flex;\n  align-items: flex-end;\n  gap: 14px;\n  margin: 56px 0 25px;\n  padding-bottom: 12px;\n  border-bottom: 1px solid #afb1a6;\n}\n\n#wemd h2::before {\n  content: counter(editorial-section, decimal-leading-zero);\n  counter-increment: editorial-section;\n  display: inline-block;\n  min-width: 42px;\n  margin-right: 4px;\n  color: #c76237;\n  font-family: \"SFMono-Regular\", Consolas, monospace;\n  font-size: 32px;\n  font-weight: 800;\n  line-height: 1;\n  letter-spacing: 0.02em;\n  vertical-align: bottom;\n}\n\n#wemd h2 .content {\n  color: #242720;\n  font-family: \"Songti SC\", \"STSong\", \"Noto Serif CJK SC\", SimSun, serif;\n  font-size: 23px;\n  font-weight: 700;\n  line-height: 1.48;\n  letter-spacing: 0.035em;\n}\n\n#wemd h3 {\n  margin: 38px 0 19px;\n}\n\n#wemd h3 .content {\n  display: inline-block;\n  padding: 7px 13px;\n  color: #f4f2e9;\n  background: #34372f;\n  font-size: 16px;\n  font-weight: 700;\n  line-height: 1.45;\n  letter-spacing: 0.055em;\n}\n\n#wemd h4 {\n  margin: 31px 0 16px;\n  padding-left: 12px;\n  border-left: 4px solid #c76237;\n}\n\n#wemd h4 .content {\n  color: #34372f;\n  font-size: 16px;\n  font-weight: 700;\n  line-height: 1.5;\n  letter-spacing: 0.035em;\n}\n\n#wemd h5,\n#wemd h6 {\n  margin: 27px 0 14px;\n}\n\n#wemd h5 .content,\n#wemd h6 .content {\n  color: #626657;\n  font-size: 15px;\n  font-weight: 700;\n  line-height: 1.5;\n}\n\n#wemd h1 .prefix,\n#wemd h1 .suffix,\n#wemd h2 .prefix,\n#wemd h2 .suffix,\n#wemd h3 .prefix,\n#wemd h3 .suffix,\n#wemd h4 .prefix,\n#wemd h4 .suffix,\n#wemd h5 .prefix,\n#wemd h5 .suffix,\n#wemd h6 .prefix,\n#wemd h6 .suffix {\n  display: none;\n}\n\n/* \u6458\u8981\u5F15\u7528 */\n#wemd blockquote {\n  border: none;\n}\n\n#wemd .multiquote-1 {\n  margin: 35px 0;\n  padding: 24px 24px 21px;\n  border-top: 3px solid #5f6453;\n  border-bottom: 1px solid #c8c9bf;\n  background: #f1f0e9;\n}\n\n#wemd .multiquote-2,\n#wemd .multiquote-3 {\n  margin: 28px 0 28px 18px;\n  padding: 7px 0 7px 18px;\n  border-left: 3px solid #c76237;\n  background: transparent;\n}\n\n#wemd .multiquote-1 p,\n#wemd .multiquote-2 p,\n#wemd .multiquote-3 p {\n  margin: 0;\n  color: #4f5347;\n  font-family: \"Songti SC\", \"STSong\", \"Noto Serif CJK SC\", SimSun, serif;\n  font-size: 16px;\n  line-height: 1.9;\n  letter-spacing: 0.035em;\n}\n\n/* \u6E05\u5355\u548C\u6B65\u9AA4 */\n#wemd ul,\n#wemd ol {\n  margin: 22px 0 28px;\n  padding-left: 24px;\n  color: #c76237;\n}\n\n#wemd ul {\n  list-style-type: square;\n}\n\n#wemd ul ul {\n  margin-top: 8px;\n  list-style-type: circle;\n}\n\n#wemd ol {\n  list-style-type: decimal-leading-zero;\n}\n\n#wemd ol ol {\n  margin-top: 8px;\n  list-style-type: lower-alpha;\n}\n\n#wemd li section {\n  margin: 7px 0;\n  color: #34362f;\n  font-size: 16px;\n  font-weight: 400;\n  line-height: 1.8;\n  text-align: left;\n}\n\n#wemd ol > li {\n  margin: 11px 0;\n  color: #c76237;\n  font-weight: 700;\n}\n\n#wemd ol > li > section {\n  padding: 10px 14px;\n  border-left: 1px solid #b8baae;\n  color: #34362f;\n  background: #f5f4ee;\n  font-weight: 400;\n}\n";
